@namespace sv_952c42f3e1d746f18c45c3ff206c0811.Components.Pages.Apply

<nav aria-label="Application steps" class="mb-4">
    <ol class="d-flex list-unstyled justify-content-between step-indicator">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var step = i;
            var isCurrent = step == CurrentStep;
            var isCompleted = CompletedSteps.Contains(step);
            var isFuture = !isCurrent && !isCompleted;

            <li class="text-center flex-fill position-relative @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "text-muted" : "")"
                role="button"
                @onclick="() => HandleStepClick(step)">
                <div class="step-circle mx-auto mb-1 rounded-circle d-flex align-items-center justify-content-center @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light border")">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                <small class="@(isCurrent ? "fw-bold text-primary" : "")">@StepNames[step]</small>
            </li>
        }
    </ol>
</nav>

<style>
    .step-circle {
        width: 36px;
        height: 36px;
        font-size: 0.875rem;
    }
    .step-indicator li.completed {
        cursor: pointer;
    }
    .step-indicator li.active .step-circle,
    .step-indicator li.completed .step-circle {
        box-shadow: 0 0 0 3px rgba(var(--bs-primary-rgb), 0.2);
    }
</style>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

